    _bp=[T('Kr. e. 265-ig: Itália meghódítása','to 265 BC: conquest of Italy'),T('Kr. e. 264–134: pun és makedón háborúk','264–134 BC: Punic and Macedonian wars'),T('Kr. e. 133–31: a köztársaság válsága','133–31 BC: crisis of the Republic'),T('Kr. e. 30 – Kr. u. 284: principatus','30 BC – AD 284: Principate'),T('285–500: késő császárkor','285–500: late Empire')]
